    int memo[205][205][205];
    string str;

    int dfs(int i, int j, int remK) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j][remK] != -1) return memo[i][j][remK];

        int res = max(dfs(i + 1, j, remK), dfs(i, j - 1, remK));
