import java.util.Arrays;

class Solution {
    private int[][][] memo;
    private String str;

    private int dfs(int i, int j, int remK) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j][remK] != -1) return memo[i][j][remK];

        int res = Math.max(dfs(i + 1, j, remK), dfs(i, j - 1, remK));
        int diff = Math.abs(str.charAt(i) - str.charAt(j));
        int cost = Math.min(diff, 26 - diff);
        if (remK >= cost) {
            res = Math.max(res, 2 + dfs(i + 1, j - 1, remK - cost));
        }

        return memo[i][j][remK] = res;
    }

    public int longestPalindromeSubsequence(String s, int k) {
        str = s;
        int n = s.length();
        memo = new int[n][n][k + 1];
        for (int[][] mat : memo) {
            for (int[] row : mat) {
                Arrays.fill(row, -1);
            }
        }
        return dfs(0, n - 1, k);
    }
}

/**
 * @param {string} s
 * @param {number} k
 * @return {number}
 */
var longestPalindromeSubsequence = function(s, k) {
    const n = s.length;
    const memo = new Map();

    function dfs(i, j, remK) {
        if (i > j) return 0;
        if (i === j) return 1;
        const key = `${i},${j},${remK}`;
        if (memo.has(key)) return memo.get(key);

        let res = Math.max(dfs(i + 1, j, remK), dfs(i, j - 1, remK));
        const diff = Math.abs(s.charCodeAt(i) - s.charCodeAt(j));
        const cost = Math.min(diff, 26 - diff);
        if (remK >= cost) {
            res = Math.max(res, 2 + dfs(i + 1, j - 1, remK - cost));
        }

        memo.set(key, res);
        return res;
    }

    return dfs(0, n - 1, k);
};
